/* @lc app=leetcode id=2327 lang=kotlin */
class Solution { fun peopleAwareOfSecret(n: Int, delay: Int, forget: Int): Int = LongArray(n + 1).apply { this[1] = 1 }.let { dp -> (2..n).fold(0L) { sharing, i -> ((sharing + (if (i - delay >= 1) dp[i - delay] else 0) - (if (i - forget >= 1) dp[i - forget] else 0) + 1000000007) % 1000000007).also { dp[i] = it } }.let { (maxOf(1, n - forget + 1)..n).sumOf { dp[it] } % 1000000007 }.toInt() } }